Here's a complete example of how to automatically generate a table of contents in a LaTeX document. This example includes all necessary commands and packages, and demonstrates how to compile the document to produce a clickable, formatted table of contents.

```latex
\documentclass[12pt, a4paper]{article}

% Load required packages
\usepackage[utf8]{inputenc}
\usepackage[T1]{fontenc}
\usepackage{geometry}
\usepackage{hyperref}

% Set page margins
\geometry{left=2.5cm, right=2.5cm, top=2.5cm, bottom=2.5cm}

% Configure hyperref for clickable links
\hypersetup{
    colorlinks=true,
    linkcolor=blue,
    urlcolor=blue,
    pdftitle={Table of Contents Example},
    pdfauthor={Your Name}
}

% Begin document
\begin{document}

% Generate the table of contents
\tableofcontents
\newpage

% Document content
\section{Introduction}
This is the introduction section of the document.

\subsection{Background}
Some background information here.

\subsection{Objectives}
List of objectives for this document.

\section{Main Content}
This is the main body of the document.

\subsection{Subsection One}
Details about the first subsection.

\subsection{Subsection Two}
Details about the second subsection.

\section{Conclusion}
Summary and final thoughts.

\end{document}
```

### Compilation Instructions

To compile this document and generate the table of contents:

1. Save the code in a file named `example.tex`.
2. Open a terminal or command prompt.
3. Compile using the following sequence:
   - `pdflatex example.tex`
   - `pdflatex example.tex` (second pass to update TOC)
   - `pdflatex example.tex` (third pass to finalize)

Alternatively, use a LaTeX editor like Overleaf or TeXShop, which can automate the compilation process.

### Key Commands and Packages

- `\documentclass{article}`: Defines the document structure.
- `\usepackage{hyperref}`: Enables clickable links in the TOC.
- `\tableofcontents`: Automatically generates the table of contents.
- `\section`, `\subsection`: Create hierarchical content that the TOC indexes.
- `\newpage`: Inserts a page break after the TOC.

This example demonstrates how to create a clean, automatically generated table of contents in LaTeX with proper formatting and interactivity.

To create a smooth Snake game in C that uses images, the best approach is to use the **SDL2 (Simple DirectMedia Layer)** library. SDL2 is the industry standard for cross-platform C game development. It handles windowing, input, and image rendering efficiently.

Below is a complete, single-file solution.

### Prerequisites

1.  **Install SDL2:**
    *   **Ubuntu/Debian:** `sudo apt-get install libsdl2-dev libsdl2-image-dev`
    *   **Windows:** Download the [SDL2 Windows SDK](https://www.libsdl.org/download-2.0.php) and add the include/library paths to your compiler.
    *   **Mac:** `brew install sdl2 sdl2_image`
2.  **Prepare Images:** You need three image files in the same folder as your C code:
    *   `snake.png` (The snake head)
    *   `snake_body.png` (The snake body segment)
    *   `food.png` (The apple/food)
    *   *(Optional)* `bg.png` (Background)
    *   *Note:* If you don't have images, the code below includes a fallback to draw colored rectangles so the game still works for testing.

### The Code (`snake.c`)

```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

// --- Configuration ---
#define SCREEN_WIDTH  800
#define SCREEN_HEIGHT 600
#define TILE_SIZE     20
#define GRID_WIDTH    (SCREEN_WIDTH / TILE_SIZE)
#define GRID_HEIGHT   (SCREEN_HEIGHT / TILE_SIZE)
#define INITIAL_SPEED 1000 // Milliseconds per move (lower is faster)

// --- Global Variables ---
SDL_Window* g_window = NULL;
SDL_Renderer* g_renderer = NULL;
SDL_Texture* g_bg_texture = NULL;
SDL_Texture* g_food_texture = NULL;
SDL_Texture* g_head_texture = NULL;
SDL_Texture* g_body_texture = NULL;

// Snake State
typedef struct {
    int x, y;
} Point;

Point g_snake[200]; // Max length
int g_snake_length = 3;
Point g_food;
int g_score = 0;
int g_direction = 0; // 0: Right, 1: Down, 2: Left, 3: Up
int g_last_move_time = 0;
int g_speed = INITIAL_SPEED;
int g_game_over = 0;

// --- Initialization ---
int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO) < 0) {
        printf("SDL_Init Error: %s\n", SDL_GetError());
        return 1;
    }

    // Initialize Image Loader
    if (IMG_Init(IMG_INIT_PNG) < 0) {
        printf("SDL_image_Init Error: %s\n", IMG_GetError());
        SDL_Quit();
        return 1;
    }

    // Create Window
    g_window = SDL_CreateWindow("C Snake Game", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!g_window) {
        printf("SDL_CreateWindow Error: %s\n", SDL_GetError());
        IMG_Quit();
        SDL_Quit();
        return 1;
    }

    // Create Renderer
    g_renderer = SDL_CreateRenderer(g_window, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!g_renderer) {
        printf("SDL_CreateRenderer Error: %s\n", SDL_GetError());
        SDL_DestroyWindow(g_window);
        IMG_Quit();
        SDL_Quit();
        return 1;
    }

    // Load Images (Fallback to colors if files missing)
    if (IMG_Load("snake.png") != NULL) {
        g_head_texture = SDL_CreateTextureFromSurface(g_renderer, IMG_Load("snake.png"));
    } else {
        // Fallback: Create a red rectangle texture
        SDL_Surface* surface = SDL_CreateRGBSurface(0, TILE_SIZE, TILE_SIZE, 32, 0xFF0000, 0x00FF00, 0x0000FF, 0x000000);
        g_head_texture = SDL_CreateTextureFromSurface(g_renderer, surface);
        SDL_FreeSurface(surface);
    }

    if (IMG_Load("snake_body.png") != NULL) {
        g_body_texture = SDL_CreateTextureFromSurface(g_renderer, IMG_Load("snake_body.png"));
    } else {
        // Fallback: Green rectangle
        SDL_Surface* surface = SDL_CreateRGBSurface(0, TILE_SIZE, TILE_SIZE, 32, 0xFF0000, 0x00FF00, 0x0000FF, 0x000000);
        g_body_texture = SDL_CreateTextureFromSurface(g_renderer, surface);
        SDL_FreeSurface(surface);
    }

    if (IMG_Load("food.png") != NULL) {
        g_food_texture = SDL_CreateTextureFromSurface(g_renderer, IMG_Load("food.png"));
    } else {
        // Fallback: Red rectangle
        SDL_Surface* surface = SDL_CreateRGBSurface(0, TILE_SIZE, TILE_SIZE, 32, 0xFF0000, 0x00FF00, 0x0000FF, 0x000000);
        g_food_texture = SDL_CreateTextureFromSurface(g_renderer, surface);
        SDL_FreeSurface(surface);
    }

    // Initialize Snake
    g_snake[0].x = 10;
    g_snake[0].y = 10;
    g_snake_length = 3;
    for (int i = 1; i < g_snake_length; i++) {
        g_snake[i].x = 10;
        g_snake[i].y = 10;
    }

    // Spawn Food
    g_food.x = 15;
    g_food.y = 15;

    // Start Game Loop
    while (1) {
        // 1. Handle Events
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) break;
            if (e.type == SDL_KEYDOWN) {
                switch (e.key.keysym.sym) {
                    case SDLK_UP:    if (g_direction != 1) g_direction = 3; break;
                    case SDLK_DOWN:  if (g_direction != 2) g_direction = 1; break;
                    case SDLK_LEFT:  if (g_direction != 3) g_direction = 2; break;
                    case SDLK_RIGHT: if (g_direction != 0) g_direction = 0; break;
                }
            }
        }

        // 2. Update Game Logic (Fixed Time Step for Smoothness)
        if (SDL_GetTicks() - g_last_move_time > g_speed) {
            g_last_move_time = SDL_GetTicks();

            // Move Snake
            int head_x = g_snake[0].x;
            int head_y = g_snake[0].y;

            switch (g_direction) {
                case 0: head_x++; break; // Right
                case 1: head_y++; break; // Down
                case 2: head_x--; break; // Left
                case 3: head_y--; break; // Up
            }

            // Check Wall Collision
            if (head_x < 0 || head_x >= GRID_WIDTH || head_y < 0 || head_y >= GRID_HEIGHT) {
                g_game_over = 1;
            }

            // Check Self Collision
            for (int i = 0; i < g_snake_length; i++) {
                if (head_x == g_snake[i].x && head_y == g_snake[i].y) {
                    g_game_over = 1;
                }
            }

            // Move Body
            for (int i = g_snake_length - 1; i > 0; i--) {
                g_snake[i] = g_snake[i - 1];
            }
            g_snake[0].x = head_x;
            g_snake[0].y = head_y;

            // Check Food
            if (head_x == g_food.x && head_y == g_food.y) {
                g_snake_length++;
                g_score++;
                // Increase speed slightly
                if (g_speed > 200) g_speed -= 5;

                // Spawn new food
                g_food.x = rand() % GRID_WIDTH;
                g_food.y = rand() % GRID_HEIGHT;

                // Prevent food spawning on snake
                for (int i = 0; i < g_snake_length; i++) {
                    if (g_food.x == g_snake[i].x && g_food.y == g_snake[i].y) {
                        g_food.x = rand() % GRID_WIDTH;
                        g_food.y = rand() % GRID_HEIGHT;
                    }
                }
            }
        }

        // 3. Render
        SDL_SetRenderDrawColor(g_renderer, 0, 0, 0, 255);
        SDL_RenderClear(g_renderer);

        // Draw Background
        if (g_bg_texture) {
            SDL_RenderCopy(g_renderer, g_bg_texture, NULL, NULL);
        } else {
            SDL_RenderFillRect(g_renderer, &SDL_Rect{0, 0, SCREEN_WIDTH, SCREEN_HEIGHT});
        }

        // Draw Food
        if (g_food_texture) {
            SDL_Rect food_rect = {g_food.x * TILE_SIZE, g_food.y * TILE_SIZE, TILE_SIZE, TILE_SIZE};
            SDL_RenderCopy(g_renderer, g_food_texture, NULL, &food_rect);
        }

        // Draw Snake
        for (int i = 0; i < g_snake_length; i++) {
            SDL_Rect rect = {g_snake[i].x * TILE_SIZE, g_snake[i].y * TILE_SIZE, TILE_SIZE, TILE_SIZE};
            if (i == 0) {
                if (g_head_texture) SDL_RenderCopy(g_renderer, g_head_texture, NULL, &rect);
            } else {
                if (g_body_texture) SDL_RenderCopy(g_renderer, g_body_texture, NULL, &rect);
            }
        }

        // Draw Score
        SDL_Color text_color = {255, 255, 255, 255};
        SDL_Surface* text_surface = SDL_CreateStringSurface(20, 20, 0, "Score: %d", g_score);
        SDL_Texture* text_texture = SDL_CreateTextureFromSurface(g_renderer, text_surface);
        SDL_RenderCopy(g_renderer, text_texture, NULL, NULL);
        SDL_FreeSurface(text_surface);
        SDL_DestroyTexture(text_texture);

        // Draw Game Over
        if (g_game_over) {
            SDL_Color red = {255, 0, 0, 255};
            SDL_Surface* surface = SDL_CreateRGBSurface(0, 200, 50, 32, 0xFF0000, 0x00FF00, 0x0000FF, 0x000000);
            SDL_Rect rect = {0, 0, 200, 50};
            SDL_FillRect(surface, &rect, &red);
            SDL_Surface* text = SDL_CreateStringSurface(20, 20, 0, "GAME OVER");
            SDL_Texture* t = SDL_CreateTextureFromSurface(g_renderer, text);
            SDL_RenderCopy(g_renderer, t, NULL, NULL);
            SDL_FreeSurface(text);
            SDL_DestroyTexture(t);
            SDL_FreeSurface(surface);
        }

        // 4. Present
        SDL_RenderPresent(g_renderer);
    }

    // Cleanup
    SDL_DestroyRenderer(g_renderer);
    SDL_DestroyWindow(g_window);
    IMG_Quit();
    SDL_Quit();
    return 0;
}
```

### How to Compile

You need to link against SDL2 and SDL2_image.

**Linux (Ubuntu/Debian):**
```bash
gcc snake.c -o snake -lSDL2 -lSDL2_image -lSDL2_image
./snake
```

**Windows (MinGW):**
```bash
gcc snake.c -o snake.exe -lSDL2main -lSDL2 -lSDL2_image
snake.exe
```

**Mac (Xcode):**
```bash
gcc snake.c -o snake -framework Cocoa -lSDL2 -lSDL2_image
./snake
```

### How to Make it "Smooth"

1.  **Fixed Time Step (`g_last_move_time`):**
    *   In the code, the snake does not move every single frame. It moves only when `SDL_GetTicks() - g_last_move_time > g_speed`.
    *   This ensures that on a 144Hz monitor, the snake doesn't move 144 times a second. It moves at a consistent speed (e.g., 10 times a second). This prevents the "jittery" feeling common in grid-based games.
2.  **V-Sync:**
    *   `SDL_RENDERER_PRESENTVSYNC` is set in the renderer creation. This synchronizes the game with your monitor's refresh rate, preventing screen tearing.
3.  **Image Rendering:**
    *   Using `SDL_RenderCopy` ensures that the images are drawn at the correct resolution and scale, rather than just drawing colored rectangles.

### How to Prepare Images

1.  Create a folder named `assets` (or put them in the same folder as `snake.c`).
2.  Create three PNG files:
    *   `snake.png`: A 20x20 pixel image of a snake head.
    *   `snake_body.png`: A 20x20 pixel image of a snake body segment.
    *   `food.png`: A 20x20 pixel image of an apple.
3.  **Important:** Ensure the images are **transparent** (RGBA) or have a solid background color that matches your game style. The code currently checks for the file existence; if the file is missing, it draws a colored rectangle (Red for head, Green for body, Red for food) so you can test the logic immediately.

### Tips for Improvement

*   **Sound:** Add `SDL_Audio` to play a "chomp" sound when eating food.
*   **High Score:** Save the score to a file using `fopen` and `fseek` to keep track of the best score.
*   **Difficulty:** You can make the game harder by reducing `g_speed` as the score increases.
*   **Smooth Movement:** If you want the snake to move pixel-by-pixel (not grid-based), you would need to change the `Point` structure to `float` and use `sin/cos` for movement, but the grid-based approach above is standard for Snake.

This guide outlines a production-grade, high-quality Cypress testing framework. It utilizes **Docker Compose** to orchestrate the application and the test runner, ensuring environment isolation and reproducibility. It leverages Cypress's native screenshot capabilities for debugging and visual regression, configured with TypeScript for type safety.

### 1. Project Structure

A modular, scalable folder structure is essential for maintainability.

```text
my-cypress-docker-framework/
├── cypress/
│   ├── e2e/
│   │   ├── login.cy.ts
│   │   └── dashboard.cy.ts
│   ├── fixtures/
│   │   └── user.json
│   ├── support/
│   │   ├── commands.ts
│   │   └── e2e.ts
│   └── config.ts
├── src/
│   ├── app/
│   │   ├── index.html
│   │   └── app.js
│   └── package.json
├── docker/
│   ├── Dockerfile
│   └── docker-compose.yml
├── .env
├── .github/
│   └── workflows/
│       └── ci.yml
└── package.json
```

### 2. Docker Configuration

We will run the **Application** and the **Cypress Runner** in separate containers within the same network. This ensures the Cypress container can access the running application without port conflicts.

#### `docker/Dockerfile` (Cypress Runner)
This image installs Node, Cypress, and mounts the project code.

```dockerfile
FROM node:18-alpine

# Create app directory
WORKDIR /app

# Install dependencies
COPY package.json ./
RUN npm install --production

# Install Cypress globally
RUN npm install -g cypress

# Copy project code
COPY . .

# Expose Cypress port
EXPOSE 5123

# Start Cypress
CMD ["cypress", "open"]
```

#### `docker/docker-compose.yml`
Orchestrates the App and the Cypress Runner.

```yaml
version: '3.8'

services:
  app:
    build:
      context: .
      dockerfile: docker/Dockerfile
    ports:
      - "3000:3000"
    environment:
      - NODE_ENV=production
      - PORT=3000
    volumes:
      - ./src:/app/src
    networks:
      - test-network

  cypress:
    build:
      context: .
      dockerfile: docker/Dockerfile
    ports:
      - "5123:5123"
    environment:
      - CYPRESS_BASE_URL=http://app:3000
    volumes:
      - ./cypress:/app/cypress
    depends_on:
      - app
    networks:
      - test-network
    command: cypress run --spec "cypress/e2e/**/*.cy.ts" --headless

networks:
  test-network:
    driver: bridge
```

### 3. Cypress Configuration (TypeScript)

This configuration handles retries, screenshots, and custom commands.

#### `cypress/config.ts`

```typescript
import { defineConfig } from 'cypress';

export default defineConfig({
  e2e: {
    baseUrl: 'http://localhost:3000', // Adjusted for local dev
    supportFile: 'cypress/support/e2e.ts',
    specPattern: 'cypress/e2e/**/*.cy.{ts,js}',
    viewportWidth: 1280,
    viewportHeight: 720,
    video: true, // Record all tests
    screenshotOnRunFailure: true,
    screenshotOnRetries: true,
    retries: {
      runMode: 2,
      openMode: 0,
    },
    screenshotsFolder: 'cypress/screenshots',
    videosFolder: 'cypress/videos',
    screenshotsOnPass: false, // Only capture on failure or specific events
  },
  env: {
    CYPRESS_BASE_URL: 'http://localhost:3000',
  },
});
```

#### `cypress/support/commands.ts`
Custom commands to make screenshot logic cleaner.

```typescript
import { Cypress } from 'cypress';

// Custom command to capture screenshot with metadata
Cypress.Commands.add('takeScreenshot', (description: string, condition: boolean = true) => {
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const filename = `screenshot-${description}-${timestamp}.png`;

  if (condition) {
    cy.screenshot(filename);
  } else {
    // Optional: Take screenshot even if test passes for visual regression
    cy.screenshot(filename, { overwrite: true });
  }
});

// Custom command to capture on specific route
Cypress.Commands.add('onRoute', (route: string) => {
  cy.on('route:complete', (route) => {
    if (route.url.includes(route)) {
      cy.screenshot(`route-${route}`);
    }
  });
});
```

#### `cypress/support/e2e.ts`
Setup file for global hooks.

```typescript
import '@testing-library/jest-dom';

// Ensure screenshots folder exists
Cypress.on('uncaught:exception', (err, runnable) => {
  // Do not rethrow the error if it's a timeout or assertion error
  if (err.message.includes('Timeout')) {
    return false;
  }
  // Re-throw the error if it's a real error
  return true;
});
```

### 4. Test Suite (E2E)

This demonstrates how to capture screenshots on failure and specific events.

#### `cypress/e2e/login.cy.ts`

```typescript
describe('Login Page', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should capture screenshot on successful login', () => {
    cy.get('input[type="email"]').type('test@example.com');
    cy.get('input[type="password"]').type('password123');
    cy.get('button[type="submit"]').click();

    // Capture screenshot on success
    cy.takeScreenshot('login-success');
    cy.url().should('include', '/dashboard');
  });

  it('should capture screenshot on failed login', () => {
    cy.get('input[type="email"]').type('wrong@example.com');
    cy.get('input[type="password"]').type('wrongpass');
    cy.get('button[type="submit"]').click();

    // Capture screenshot on failure
    cy.takeScreenshot('login-failure', false);
    cy.url().should('include', '/login');
  });
});
```

#### `cypress/e2e/dashboard.cy.ts`

```typescript
describe('Dashboard', () => {
  it('should capture screenshot on route change', () => {
    cy.visit('/dashboard');
    cy.takeScreenshot('dashboard-initial');

    cy.get('button[data-testid="logout"]').click();
    cy.url().should('include', '/login');
    cy.takeScreenshot('dashboard-logout');
  });
});
```

### 5. CI/CD Integration (GitHub Actions)

This workflow spins up the Docker containers and runs the tests.

#### `.github/workflows/ci.yml`

```yaml
name: Cypress E2E Tests

on:
  push:
    branches: [ main ]
  pull_request:
    branches: [ main ]

jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3

      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@v2

      - name: Build and Run Docker Compose
        run: |
          docker-compose up --build -d
          sleep 10 # Wait for app to start
          docker-compose exec cypress cypress run --spec "cypress/e2e/**/*.cy.ts" --headless

      - name: Upload Screenshots
        uses: actions/upload-artifact@v3
        if: always()
        with:
          name: cypress-screenshots
          path: cypress/screenshots
          retention-days: 30
```

### 6. Best Practices & Enhancements

To ensure this framework remains "High Quality," consider the following enhancements:

1.  **Visual Regression Testing:**
    For pixel-perfect UI testing, integrate the `cypress-visual-regression` plugin.
    ```bash
    npm install cypress-visual-regression
    ```
    Configure `cypress.config.ts` to use `visualRegressionTests` instead of standard screenshots.

2.  **Environment Variables:**
    Use `.env` files to manage API keys or base URLs. Ensure Docker Compose passes these correctly.
    ```bash
    # .env
    CYPRESS_BASE_URL=http://localhost:3000
    ```

3.  **Test Isolation:**
    Ensure tests do not share state. Use `beforeEach` to clear cookies and localStorage.
    ```typescript
    beforeEach(() => {
      cy.clearCookies();
      cy.clearLocalStorage();
    });
    ```

4.  **Reporting:**
    For better reporting, integrate `cypress-reporter` or `allure-cypress` to generate HTML reports with screenshots embedded.

5.  **Security:**
    Never commit secrets. Use Docker secrets or environment variables for sensitive data.

### 7. Running Locally

To test this framework locally:

1.  **Install Dependencies:**
    ```bash
    npm install
    ```
2.  **Start Docker Containers:**
    ```bash
    docker-compose up --build
    ```
3.  **Run Cypress:**
    ```bash
    npm run cypress:run
    ```
    *Note: Ensure `CYPRESS_BASE_URL` in `cypress.config.ts` matches the `app` service port.*

This setup provides a robust, isolated, and reproducible testing environment that scales well with your application's complexity.
